-- ============================================
-- LUMA — Thème 3 : LONG 2/3 x4 — Un entretien collectif face à des concurrents
-- ============================================


update scenarios set content = '{"characters": {"assessor": "l''évaluateur", "competitor1": "Jamie", "competitor2": "Taylor", "competitor3": "Morgan"}, "start_node": "n1", "nodes": {"n1": {"speaker": "assessor", "text": "Welcome everyone. Today you''ll work together on a case study, as a group of four.", "text_fr": "Bienvenue à tous. Aujourd''hui vous allez travailler ensemble sur une étude de cas, en groupe de quatre.", "choices": [{"text": "Sounds great, looking forward to collaborating.", "text_fr": "Ça a l''air super, j''ai hâte de collaborer.", "next": "n2"}, {"text": "(Nod and glance at the other candidates, sizing up the room.)", "text_fr": "(Hoche la tête et regarde les autres candidats, jaugeant la pièce.)", "next": "n2"}]}, "n2": {"speaker": "assessor", "text": "Your task: propose a plan to reduce customer churn by 20% in six months. You have 20 minutes.", "text_fr": "Votre tâche : proposer un plan pour réduire l''attrition client de 20% en six mois. Vous avez 20 minutes.", "choices": [{"text": "(Take initiative) Should we start by defining our approach together?", "text_fr": "(Prends l''initiative) On devrait commencer par définir notre approche ensemble ?", "next": "n3"}, {"text": "(Wait to see how the group naturally organizes first.)", "text_fr": "(Attends de voir comment le groupe s''organise naturellement d''abord.)", "next": "n3b"}]}, "n3": {"speaker": "competitor1", "text": "Good idea. I think we should focus on pricing changes first.", "text_fr": "Bonne idée. Je pense qu''on devrait se concentrer sur les changements de prix d''abord.", "choices": [{"text": "That''s one angle — what about looking at customer support quality too?", "text_fr": "C''est un angle — et si on regardait aussi la qualité du support client ?", "next": "n4"}, {"text": "Interesting, let''s build on that and see what data supports it.", "text_fr": "Intéressant, développons ça et voyons quelles données le soutiennent.", "next": "n4"}]}, "n3b": {"speaker": "competitor2", "text": "I''ll kick things off — let''s map out where customers are actually leaving from.", "text_fr": "Je vais démarrer — cartographions d''où les clients partent réellement.", "choices": [{"text": "Great starting point, I can help track the data on that.", "text_fr": "Excellent point de départ, je peux aider à suivre les données là-dessus.", "next": "n4"}, {"text": "Good idea, though I''d also want to hear from support teams directly.", "text_fr": "Bonne idée, même si j''aimerais aussi entendre les équipes support directement.", "next": "n4"}]}, "n4": {"speaker": "competitor3", "text": "(Somewhat dominating the conversation) I really think my idea about loyalty programs is the strongest.", "text_fr": "(Dominant un peu la conversation) Je pense vraiment que mon idée sur les programmes de fidélité est la plus forte.", "choices": [{"text": "That''s a solid idea — how would it fit alongside the other points raised?", "text_fr": "C''est une bonne idée — comment ça s''intègre avec les autres points soulevés ?", "next": "n5"}, {"text": "(Gently redirect) Let''s make sure everyone gets a chance to build on ideas together.", "text_fr": "(Redirige gentiment) Assurons-nous que tout le monde puisse développer les idées ensemble.", "next": "n5b"}]}, "n5": {"speaker": "competitor3", "text": "Fair point, I suppose it could work alongside pricing changes.", "text_fr": "Point valable, je suppose que ça pourrait fonctionner avec les changements de prix.", "choices": [{"text": "Exactly, let''s combine both into our final plan.", "text_fr": "Exactement, combinons les deux dans notre plan final.", "next": "n6"}]}, "n5b": {"speaker": "competitor1", "text": "(Nods, slightly relieved) Yeah, good point — let''s hear from everyone.", "text_fr": "(Hoche la tête, un peu soulagé) Ouais, bon point — écoutons tout le monde.", "choices": [{"text": "Thanks — so, what does everyone think is our strongest combined approach?", "text_fr": "Merci — alors, qu''est-ce que tout le monde pense être notre approche combinée la plus forte ?", "next": "n6"}]}, "n6": {"speaker": "competitor2", "text": "I think combining pricing flexibility with better support response times is strongest.", "text_fr": "Je pense que combiner la flexibilité des prix avec de meilleurs temps de réponse support est le plus fort.", "choices": [{"text": "Agreed, let''s structure our presentation around those two pillars.", "text_fr": "D''accord, structurons notre présentation autour de ces deux piliers.", "next": "n7"}]}, "n7": {"speaker": "assessor", "text": "Two minutes left — who''s presenting your group''s plan?", "text_fr": "Deux minutes restantes — qui présente le plan de votre groupe ?", "choices": [{"text": "I''m happy to present, if the group agrees.", "text_fr": "Je suis content de présenter, si le groupe est d''accord.", "next": "n8"}, {"text": "(Look to the group) Does anyone want to present, or should we pick together?", "text_fr": "(Regarde le groupe) Quelqu''un veut présenter, ou on choisit ensemble ?", "next": "n8b"}]}, "n8": {"speaker": "competitor1", "text": "Sounds good to me, go for it.", "text_fr": "Ça me va, vas-y.", "choices": [{"text": "(Present the group''s combined plan clearly and confidently.)", "text_fr": "(Présente le plan combiné du groupe clairement et avec assurance.)", "next": "n9"}]}, "n8b": {"speaker": "competitor3", "text": "Actually, I think you''ve synthesized our ideas well — you should present.", "text_fr": "En fait, je pense que tu as bien synthétisé nos idées — tu devrais présenter.", "choices": [{"text": "Happy to, thank you for the trust.", "text_fr": "Avec plaisir, merci pour la confiance.", "next": "n9"}]}, "n9": {"speaker": "assessor", "text": "(Listening carefully to the presentation, taking notes.) Great teamwork, everyone.", "text_fr": "(Écoute attentivement la présentation, prend des notes.) Excellent travail d''équipe, tout le monde.", "choices": [{"text": "Thank you, it was great collaborating with this group.", "text_fr": "Merci, c''était super de collaborer avec ce groupe.", "next": "n10"}]}, "n10": {"speaker": "assessor", "text": "One follow-up — how did you all handle disagreements during the exercise?", "text_fr": "Une question de suivi — comment avez-vous tous géré les désaccords pendant l''exercice ?", "choices": [{"text": "We made sure every voice got heard before settling on a direction.", "text_fr": "On s''est assurés que chaque voix soit entendue avant de se fixer sur une direction.", "next": "n11"}, {"text": "We focused on the data and let that guide our final decision.", "text_fr": "On s''est concentrés sur les données et on a laissé ça guider notre décision finale.", "next": "n11"}]}, "n11": {"speaker": "assessor", "text": "That''s exactly the kind of collaboration we look for. Thank you all for today.", "text_fr": "C''est exactement le genre de collaboration qu''on recherche. Merci à tous pour aujourd''hui.", "choices": [{"text": "Thank you for the opportunity, this was a great exercise.", "text_fr": "Merci pour l''opportunité, c''était un excellent exercice.", "next": "end_collaborative"}]}, "end_collaborative": {"speaker": "assessor", "text": "We''ll be reviewing everyone''s contributions carefully. Best of luck to you all.", "text_fr": "On va examiner attentivement les contributions de chacun. Bonne chance à tous.", "end": true, "ending_label": "Collaboration réussie sans écraser les autres 🤝🏆"}}}'::jsonb, is_playable = true
where title = 'Un entretien collectif face à des concurrents'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
